function logicTokens(s){var toks=[];var i=0;
  var two=['->','<->','=>','<='];
  while(i<s.length){var c=s[i];
    if(/\s/.test(c)){i++;continue;}
    if(c==='('||c===')'||c==='!'||c==='&'||c==='|'||c==='^'){toks.push(c);i++;continue;}
    if(c==='-'&&s[i+1]==='>'){toks.push('->');i+=2;continue;}
    if(c==='<'&&s[i+1]==='-'&&s[i+2]==='>'){toks.push('<->');i+=3;continue;}
    if(/[01]/.test(c)){toks.push('num');i++;continue;}
    if(/[A-Za-z]/.test(c)){var j=i;while(j<s.length&&/[A-Za-z0-9_]/.test(s[j]))j++;toks.push(s.slice(i,j));i=j;continue;}
    throw new Error('bad char '+c);
  }
  return toks;
}
function logicParse(toks){
  var i=0;
  function peek(){return toks[i];}
  function eat(){return toks[i++];}
  function parseImpl(){var v=parseOr();while(peek()==='->'||peek()==='<->'){var op=eat();var r=parseOr();v={op:op,a:v,b:r};}return v;}
  function parseOr(){var v=parseXor();while(peek()==='|'){eat();v={op:'|',a:v,b:parseXor()};}return v;}
  function parseXor(){var v=parseAnd();while(peek()==='^'){eat();v={op:'^',a:v,b:parseAnd()};}return v;}
  function parseAnd(){var v=parseNot();while(peek()==='&'){eat();v={op:'&',a:v,b:parseNot()};}return v;}
  function parseNot(){if(peek()==='!'){eat();return {op:'!',a:parseNot()};}return parseAtom();}
  function parseAtom(){var t=peek();if(t==='('){eat();var v=parseImpl();if(peek()===')')eat();return v;}
    if(t==='num'||t==='0'||t==='1'){eat();return {op:'lit',v:1};}
    if(t==='T'||t==='F'){eat();return {op:'lit',v:t==='T'?1:0};}
    if(/^[A-Za-z]/.test(t)){eat();return {op:'var',name:t};}
    throw new Error('unexpected');}
  var ast=parseImpl();if(i<toks.length)throw new Error('trailing');return ast;
}
function logicVars(ast,set){if(!ast)return;if(ast.op==='var')set[ast.name]=1;if(ast.a)logicVars(ast.a,set);if(ast.b)logicVars(ast.b,set);}
function logicEval(ast,asg){
  if(ast.op==='lit')return ast.v;
  if(ast.op==='var')return asg[ast.name]?1:0;
  if(ast.op==='!')return logicEval(ast.a,asg)?0:1;
  var a=logicEval(ast.a,asg),b=logicEval(ast.b,asg);
  if(ast.op==='&')return (a&&b)?1:0;
  if(ast.op==='|')return (a||b)?1:0;
  if(ast.op==='^')return (a^b)?1:0;
  if(ast.op==='->')return (a&&!b)?0:1;
  if(ast.op==='<->')return (a===b)?1:0;
  return 0;
}
function logicTable(expr){
  var toks=logicTokens(expr);var ast=logicParse(toks);var vs={};logicVars(ast,vs);
  var names=Object.keys(vs).sort();var rows=[];
  var n=1<<names.length;
  for(var mask=0;mask<n;mask++){var asg={};for(var k=0;k<names.length;k++)asg[names[k]]=(mask>>k)&1;rows.push({a:asg,v:logicEval(ast,asg)});}
  return {vars:names,rows:rows};
}
var EXPORTS={logicTokens:logicTokens,logicParse:logicParse,logicEval:logicEval,logicTable:logicTable};


